export async function runSeed() {
  console.log('🌱 [Seed] Iniciando população de profissionais, clientes e agendamentos de exemplo no MySQL...');
  const conn = await pool.getConnection();

  try {
    const hashedPassword = await bcrypt.hash('123456', 10);

    for (const pro of INITIAL_PROFESSIONALS) {
      const [existing] = await conn.query('SELECT id FROM professionals WHERE id = ? OR email = ?', [pro.id, pro.email]);

      if (existing.length === 0) {
        await conn.query(
          `INSERT INTO professionals 
           (id, name, commercial_name, category, avatar, cover_image, email, password, phone, 
            street, number, neighborhood, complement, city, state, country, address, 
            rating, review_count, bio, featured, payment_methods)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          [
            pro.id, pro.name, pro.commercial_name, pro.category, pro.avatar, pro.cover_image,
            pro.email, hashedPassword, pro.phone,
            pro.street, pro.number, pro.neighborhood, pro.complement,
            pro.city, pro.state, pro.country, pro.address,
            pro.rating, pro.review_count, pro.bio, pro.featured, pro.payment_methods
          ]
        );
        console.log(`  ✓ Profissional "${pro.commercial_name}" inserido`);
      }

      // Horários (Schedule)
      const [existingSchedule] = await conn.query('SELECT id FROM schedules WHERE professional_id = ?', [pro.id]);
      if (existingSchedule.length === 0) {
        await conn.query(
          `INSERT INTO schedules (professional_id, days_of_week, start_hour, end_hour, lunch_start, lunch_end, slot_interval)
           VALUES (?, ?, ?, ?, ?, ?, ?)`,
          [
            pro.id, pro.schedule.days_of_week, pro.schedule.start_hour,
            pro.schedule.end_hour, pro.schedule.lunch_start, pro.schedule.lunch_end,
            pro.schedule.slot_interval
          ]
        );
      }

      // Serviços
      for (const srv of pro.services) {
        const [existingSrv] = await conn.query('SELECT id FROM services WHERE id = ?', [srv.id]);
        if (existingSrv.length === 0) {
          await conn.query(
            `INSERT INTO services (id, professional_id, name, price, duration, description)
             VALUES (?, ?, ?, ?, ?, ?)`,
            [srv.id, pro.id, srv.name, srv.price, srv.duration, srv.description]
          );
        }
      }
    }

    // Inserir Clientes de Exemplo
    for (const cli of INITIAL_CLIENTS) {
      const [existingCli] = await conn.query('SELECT id FROM clients WHERE id = ? OR email = ?', [cli.id, cli.email]);
      if (existingCli.length === 0) {
        await conn.query(
          `INSERT INTO clients (id, name, email, phone, password)
           VALUES (?, ?, ?, ?, ?)`,
          [cli.id, cli.name, cli.email, cli.phone || '', hashedPassword]
        );
        console.log(`  ✓ Cliente "${cli.name}" inserido`);
      }
    }

    // Inserir Agendamentos de Exemplo
    for (const bkg of INITIAL_BOOKINGS) {
      const [existingBkg] = await conn.query('SELECT id FROM bookings WHERE id = ?', [bkg.id]);
      if (existingBkg.length === 0) {
        const dateStr = typeof bkg.date === 'string' ? bkg.date.slice(0, 10) : new Date(bkg.date).toISOString().slice(0, 10);
        await conn.query(
          `INSERT INTO bookings (id, professional_id, service_id, client_name, client_email, client_phone, date, time, price, duration, status)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          [bkg.id, bkg.professional_id, bkg.service_id, bkg.client_name, bkg.client_email, bkg.client_phone, dateStr, bkg.time, bkg.price, bkg.duration, bkg.status || 'confirmed']
        );
        console.log(`  ✓ Agendamento ${bkg.id} (${bkg.client_name}) inserido`);
      }
    }

    console.log('🎉 [Seed] Todos os usuários de exemplo foram inseridos com sucesso!');
  } catch (error) {
    console.error('❌ [Seed] Erro ao popular banco de dados:', error);
  } finally {
    conn.release();
  }
}

// Executa se chamado diretamente via node
if (process.argv[1]?.includes('seed.js')) {
  runSeed().then(() => process.exit(0));
}
